public static HcmPositionDetail getPositionDetails(HcmPositionRecId _position,
    utcdatetime _asofDateTime = DateTimeUtil::utcNow())
{
    HcmPositionDetail positionDetail;

    positionDetail = HcmPositionDetail::findByPosition(_position, _asofDateTime, _asofDateTime);

    return positionDetail;
}

